arguments.content:
# noVNC web interface for the Windows 3.11 QEMU VM.
#
# Serves the noVNC static files from /usr/share/novnc on port 80, and proxies
# the WebSocket path /websockify to QEMU's VNC server on 127.0.0.1:5901 so a
# browser can connect to the VM without a native VNC client.
#
# Usage in browser:  http://<host>/vnc.html  (then connect to host:80, path /websockify)

server {
    listen 80 default_server;
    listen [::]:80 default_server;

    server_name _;

    # noVNC static assets
    root /usr/share/novnc;
    index vnc.html;

    location / {
        try_files $uri $uri/ =404;
    }

    # WebSocket proxy to QEMU's VNC (5901).
    # QEMU's VNC speaks the WebSocket subprotocol natively, so no separate
    # websockify process is needed.
    location /websockify {
        proxy_pass http://127.0.0.1:5901;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }
}

arguments.new_string:
# WebSocket proxy to websockify, which bridges WebSocket<->RFB to QEMU's VNC
# on 127.0.0.1:5901. QEMU's VNC speaks RFB (not WebSocket), so websockify
# (running on 127.0.0.1:6080) is the required translator.
location /websockify {
    proxy_pass http://127.0.0.1:6080;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
    proxy_set_header Host $host;
    proxy_read_timeout 3600s;
    proxy_send_timeout 3600s;
}

