arguments.command:
# Back up the original nginx.conf, then replace the inline server block with an include of sites-enabled.
cp /etc/nginx/nginx.conf /etc/nginx/nginx.conf.bak

cat > /etc/nginx/nginx.conf <<'EOF'
user  root;
worker_processes  1;


events {
    worker_connections 4096;
}

http {
    include       mime.types;
    default_type  application/octet-stream;

    # Sending file Optimization
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;

    # Keepalive Connection
    keepalive_timeout 65;

    # noVNC site (port 80 -> WebSocket proxy to QEMU VNC via websockify)
    include /etc/nginx/sites-enabled/*;
}
EOF

echo "=== new nginx.conf ==="
cat -n /etc/nginx/nginx.conf
echo "=== test ==="
nginx -t 2>&1
echo "=== reload ==="
nginx -s reload 2>&1
sleep 1
echo "=== HTTP fetch noVNC page ==="
curl -sS -o /dev/null -w "HTTP %{http_code}  size=%{size_download}\n" http://127.0.0.1/vnc.html
echo "=== HTTP fetch root ==="
curl -sS -o /dev/null -w "HTTP %{http_code}  size=%{size_download}\n" http://127.0.0.1/
echo "=== content check ==="
curl -sS http://127.0.0.1/vnc.html | grep -iE "noVNC|<title>" | head -3
echo "=== WebSocket proxy path (expect 400 from websockify on plain GET) ==="
curl -sS -o /dev/null -w "HTTP %{http_code}\n" http://127.0.0.1/websockify

